CREATE TABLE platform_policy_revision (
 revision integer PRIMARY KEY CHECK(revision>0),payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),digest text NOT NULL CHECK(digest ~ '^[a-f0-9]{64}$'),
 created_by text REFERENCES app_actor(id),reason text NOT NULL CHECK(length(trim(reason)) BETWEEN 10 AND 3000),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(revision=1 OR created_by IS NOT NULL)
);
CREATE TRIGGER immutable_platform_policy_revision BEFORE UPDATE OR DELETE ON platform_policy_revision FOR EACH ROW EXECUTE FUNCTION app_immutable();
CREATE TABLE platform_policy (
 singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),revision integer NOT NULL REFERENCES platform_policy_revision(revision),version integer NOT NULL DEFAULT 1 CHECK(version>0),updated_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE TABLE platform_policy_command (
 id uuid PRIMARY KEY,actor_id text NOT NULL REFERENCES app_actor(id),request_key uuid NOT NULL,digest text NOT NULL CHECK(digest ~ '^[a-f0-9]{64}$'),revision integer NOT NULL REFERENCES platform_policy_revision(revision),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(actor_id,request_key)
);
CREATE TRIGGER immutable_platform_policy_command BEFORE UPDATE OR DELETE ON platform_policy_command FOR EACH ROW EXECUTE FUNCTION app_immutable();
CREATE FUNCTION guard_platform_policy_update() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' OR NEW.singleton IS DISTINCT FROM OLD.singleton OR NEW.version<>OLD.version+1 OR NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION 'Platform policy history must advance exactly once'; END IF;RETURN NEW;
END $$;
CREATE TRIGGER platform_policy_progression BEFORE UPDATE OR DELETE ON platform_policy FOR EACH ROW EXECUTE FUNCTION guard_platform_policy_update();
CREATE FUNCTION require_platform_policy_publisher() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.revision>1 AND NOT EXISTS(SELECT 1 FROM app_actor WHERE id=NEW.created_by AND role='SUPER_ADMIN' AND NOT suspended AND NOT is_test_fixture) THEN RAISE EXCEPTION 'Current platform publisher authority required' USING ERRCODE='23514'; END IF;RETURN NEW;
END $$;
CREATE TRIGGER platform_publisher BEFORE INSERT ON platform_policy_revision FOR EACH ROW EXECUTE FUNCTION require_platform_policy_publisher();
INSERT INTO platform_policy_revision(revision,payload,digest,reason)VALUES(1,$policy${"consignedDefaults":{"cosigner":7000,"agency":1000,"platform":1000,"maintenance":1000},"termsTitle":"Rent2Go marketplace terms","termsText":"Rent2Go connects renters and Cosigners with independently approved car rental and tour agencies. Each agency supplies its own service terms, prices, eligibility requirements and support contact. Review the exact quotation and service agreement before acceptance. A cart, request or quotation hold alone does not confirm a paid booking.\n\nRefundable deposits are kept separate from service revenue. Charges, credits, refunds, withdrawals and remittances follow their recorded review and payment steps. An upload or approval alone is not proof of payment. Simulated financial outcomes are identified and move no money.\n\nProvide accurate information and submit only documents you are authorized to share. Document text assistance requires separate consent and does not replace human review. Use your account-status portal for information, correction, deactivation and reactivation requests. Necessary booking, financial, agreement, consent and evidence history is retained through those reviews.\n\nGPS tracking and geofencing are excluded. Agencies may manage their own separate tracking arrangements. Earlier accepted quotations, agreements and financial records keep the policy snapshots recorded for them.","inactiveEvidenceReviewDays":null,"faqs":[{"question":"When is my booking confirmed?","answer":"Submit your request, complete the document review, review the quotation, sign the exact agreement and complete the required payment review. The saved booking status explains the next step. A cart does not reserve a vehicle or tour seat."},{"question":"How do Cosigner earnings work?","answer":"The starting consigned-car shares are 70% Cosigner, 10% agency, 10% Rent2Go and 10% maintenance. The exact agency and Cosigner agreement may set different shares totaling 100%. Deposits are separate and maintenance reserves are not withdrawable owner earnings."},{"question":"Do simulated payments transfer money?","answer":"No. Simulated card, GCash and PayPal outcomes are clearly identified. Manual payments require the applicable external-payment evidence and independent review. An approval or upload alone is not confirmation of receipt."},{"question":"Does document text assistance approve my documents?","answer":"No. It is optional assistance for the exact document you consent to send. An authorized reviewer must compare the document and record the separate decision."},{"question":"Can I request account correction or deactivation?","answer":"Open Account and privacy requests to submit an exact request. A Super Admin records an independent review. Unfinished obligations must be resolved before voluntary deactivation, and required historical records are retained."},{"question":"Does Rent2Go track vehicle locations?","answer":"GPS tracking and geofencing are outside the system scope. Agencies may use their own separate tracking arrangements."}]}$policy$,'0b974184f28d8cd29921589cf259c55d2af3f345b69e1f1b51ab6d0ef637d4a4','Initial marketplace scope and starting defaults from the approved system design.');
INSERT INTO platform_policy(singleton,revision)VALUES(true,1);
ALTER TABLE partner_application ADD COLUMN platform_defaults_revision integer REFERENCES platform_policy_revision(revision);
ALTER TABLE booking_quotation ADD COLUMN platform_terms_revision integer REFERENCES platform_policy_revision(revision);
CREATE FUNCTION preserve_quote_platform_terms() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE p platform_policy_revision%ROWTYPE; BEGIN
 IF NEW.platform_terms_revision IS NULL THEN RETURN NEW; END IF;
 SELECT * INTO STRICT p FROM platform_policy_revision WHERE revision=NEW.platform_terms_revision;
 IF NEW.public_snapshot->'platformTerms' IS DISTINCT FROM jsonb_build_object('revision',p.revision,'digest',p.digest,'title',p.payload->>'termsTitle','text',p.payload->>'termsText') THEN RAISE EXCEPTION 'Quotation must preserve the exact platform terms snapshot' USING ERRCODE='23514'; END IF;RETURN NEW;
END $$;
CREATE TRIGGER quotation_platform_terms BEFORE INSERT ON booking_quotation FOR EACH ROW EXECUTE FUNCTION preserve_quote_platform_terms();
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='rent2go_app') THEN
 GRANT SELECT,INSERT ON platform_policy_revision,platform_policy_command TO rent2go_app;GRANT SELECT,UPDATE ON platform_policy TO rent2go_app;
END IF;END $$;
